import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第八卦 比 水地比 坎上坤下","description":"周易 - 第八卦 比 水地比 坎上坤下","frontmatter":{"title":"第八卦 比 水地比 坎上坤下","description":"周易 - 第八卦 比 水地比 坎上坤下"},"headers":[],"relativePath":"classics/zhouyi/009.md","filePath":"classics/zhouyi/009.md"}'),l={name:"classics/zhouyi/009.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="比" tabindex="-1">比 <a class="header-anchor" href="#比" aria-label="Permalink to “比”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>吉。原筮元永貞，無咎。不寧方來，後夫兇。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>比，吉也，比，輔也，下順從也。原筮元永貞，無咎，以剛中也。不寧方來，上下應也。後夫兇，其道窮也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>地上有水，比；先王以建萬國，親諸侯。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>有孚比之，無咎。有孚盈缶，終 來有他，吉。象曰：比之初六，有他吉也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>比自內，貞吉。象曰：比之自內，不自失也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>比之匪人。象曰：比之匪人，不亦傷乎！</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>外比之，貞吉。象曰：外比於賢，以從上也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>顯比，王用三驅，失前禽。邑人不誡，吉。象曰：顯比之吉，位正中也。舍逆取順，失前禽也。邑人不誡，上使中也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>比之無首，兇。象曰：比之無首，無所終也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
